
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_camy_b3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_camy_b3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.494910510308865e+00, -3.428372745180194e+00, -3.335185398863893e+00, -3.206196787110249e+00, -3.030635326429867e+00, -2.797379773813363e+00, -2.497924333923884e+00, -2.131566407271606e+00, -1.711734451435055e+00, -1.266996057256198e+00, -8.291328095253434e-01, -5.435318866358103e-01, -4.629560646591674e-01, -3.761051080805224e-01, -2.582988258631945e-01, -1.423846181262670e-01, -6.487447827824795e-02, -3.643067551590727e-02, -2.185474241706810e-02, -1.466429651099943e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


